# 第17章高级数据表示

数据表示要与需要的操作一起设计。保存电影记录，不只是选一个结构，还要决定有效项如何计数、顺序怎样维持、容量不足怎么办，以及谁负责释放节点。相同的数据可以放在数组、链表或树中，但操作成本和约束会随表示改变。

### 节点顺序由next连接决定（完整C程序）

```c
#include <stdio.h>
#include <stddef.h>
struct film {
    char title[16];
    int rating;
    struct film *next;
};
struct film third = {"Dune", 7, NULL};
struct film first = {"Moss", 8, NULL};
struct film second = {"River", 9, NULL};
int main(void)
{
    first.next = &second;
    second.next = &third;
    struct film *head = &first;
    const struct film *current = head;
    while (current != NULL) {
        printf("%s:%d\n", current->title, current->rating);
        current = current->next;
    }
    printf("head=%s\n", head->title);
    return 0;
}
```

**输入**：无需输入。

**真实C6运行结果**：

```text
Moss:8
River:9
Dune:7
head=Moss
```

三个节点按声明顺序并不构成目标列表，`next`连接才决定访问顺序。遍历使用独立指针，保留头入口以便再次访问；末节点的空指针提供终止条件。

本章先比较数组与链式表示，再把操作收束为列表、队列和二叉查找树的接口。重点是保持表示不变量、处理边界，并让接口对应需要的操作。

# 17.1 研究数据表示

先列出需要保存的信息和操作，再选择表示方式。电影记录的片名与评级适合放在一个结构中，多个记录可放在结构数组；数组容量与已经取得的有效记录数必须分开。

### 完整记录通过检查后才增加有效项数（完整C程序）

```c
#include <stdio.h>
#include <string.h>
#define CAPACITY 3
struct film {
    char title[16];
    int rating;
};
int read_title(char text[], int capacity)
{
    if (fgets(text, capacity, stdin) == NULL)
        return 0;
    char *newline = strchr(text, '\n');
    if (newline != NULL) {
        *newline = '\0';
        return 1;
    }
    int ch = getchar();
    if (ch == '\n' || ch == EOF)
        return 1;
    while (ch != '\n' && ch != EOF)
        ch = getchar();
    return -1;
}
int main(void)
{
    struct film movies[CAPACITY];
    int count = 0;
    while (count < CAPACITY) {
        int status = read_title(movies[count].title, 16);
        if (status == 0)
            break;
        if (status < 0) {
            puts("title too long");
            break;
        }
        if (movies[count].title[0] == '\0')
            break;
        if (scanf("%d", &movies[count].rating) != 1) {
            puts("missing rating");
            break;
        }
        if (movies[count].rating < 0 || movies[count].rating > 10) {
            puts("rating rejected");
            break;
        }
        int ch = getchar();
        while (ch != '\n' && ch != EOF)
            ch = getchar();
        /* 片名和评级都有效，才把此项纳入列表。 */
        ++count;
    }
    printf("count=%d\n", count);
    for (int i = 0; i < count; ++i)
        printf("%s:%d\n", movies[i].title, movies[i].rating);
    return 0;
}
```

**输入**：

```text
Moss
8
River
10

```

**真实C6运行结果**：

```text
count=2
Moss:8
River:10
```

这个完整小例容量为3、片名最多15个字符，评级范围0～10。只有片名和评级都有效才增加`count`；超长片名、缺失评级和越界评级都不会把半条记录纳入展示。输入数字沿用可表示为`int`的约定，`scanf`并不是任意长数字文本的完整校验器。

### 动态数组仍有连续容量和有效项数（完整标准C阅读程序）

malloc、free与结构整体赋值不在C6范围。

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
struct film {
    char title[16];
    int rating;
};
int main(void)
{
    size_t capacity = 3;
    if (capacity > SIZE_MAX / sizeof(struct film))
        return EXIT_FAILURE;
    struct film *movies = malloc(capacity * sizeof *movies);
    if (movies == NULL)
        return EXIT_FAILURE;
    struct film first = {"Moss", 8};
    struct film second = {"River", 9};
    movies[0] = first;
    movies[1] = second;
    size_t count = 2;
    printf("capacity=%zu count=%zu\n", capacity, count);
    for (size_t i = 0; i < count; ++i)
        printf("%s:%d\n", movies[i].title, movies[i].rating);
    free(movies);
    return 0;
}
```

**教学预期（非本平台实测）**：容量检查及分配成功时，输出capacity=3 count=2，再输出Moss:8和River:9。第三个位置没有有效记录，不读取；最后释放整块数组。

动态分配把容量选择推迟到运行时，但仍需要容量、乘积溢出、失败与有效项数检查，也不能超过已申请空间。它不会自动按每一次追加扩容。选择表示还涉及访问模式、顺序、空间成本，而不是一律把固定数组换成链表。

# 17.2 从数组到链表

一次分配多个结构形成连续数组，可以用下标访问；多次独立分配节点则不能假定地址相邻。链表用每个节点内的`next`记录后继，而不靠地址加一个结构大小去猜下一个节点。

### 节点顺序由next连接决定（完整C程序）

```c
#include <stdio.h>
#include <stddef.h>
struct film {
    char title[16];
    int rating;
    struct film *next;
};
struct film third = {"Dune", 7, NULL};
struct film first = {"Moss", 8, NULL};
struct film second = {"River", 9, NULL};
int main(void)
{
    first.next = &second;
    second.next = &third;
    struct film *head = &first;
    const struct film *current = head;
    while (current != NULL) {
        printf("%s:%d\n", current->title, current->rating);
        current = current->next;
    }
    printf("head=%s\n", head->title);
    return 0;
}
```

**输入**：无需输入。

**真实C6运行结果**：

```text
Moss:8
River:9
Dune:7
head=Moss
```

这里使用三个现成的静态存储期节点，把连接与分配暂时分开观察，不能对它们调用`free`。这是真实的链接遍历，但没有冒充动态节点申请；后面的完整动态例另行给出。

链表需要保存头入口，并让最后一项指向`NULL`。单向列表若不另存尾指针，追加前常要走到末尾；保存尾指针可以减少这一步，但每次修改都必须维护它。

# 17.2.1 使用链表

动态链表的关键是成功建立节点后才把它接入已有结构。分配失败时不能先改断旧连接；遍历只移动临时指针，清理则在释放当前节点前取得后继地址。

### 节点准备完毕后接入，清理时先保存后继（完整标准C阅读程序）

动态分配和释放不在C6范围。

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
struct node {
    char title[16];
    int rating;
    struct node *next;
};
struct list {
    struct node *head;
    struct node *tail;
    int count;
};
int append(struct list *list, const char *title, int rating)
{
    if (strlen(title) >= 16 || rating < 0 || rating > 10 || list->count == 3)
        return 0;
    struct node *node = malloc(sizeof *node);
    if (node == NULL)
        return 0;
    strcpy(node->title, title);
    node->rating = rating;
    node->next = NULL;
    if (list->tail == NULL)
        list->head = node;
    else
        list->tail->next = node;
    list->tail = node;
    ++list->count;
    return 1;
}
void clear(struct list *list)
{
    struct node *node = list->head;
    while (node != NULL) {
        struct node *next = node->next;
        free(node);
        node = next;
    }
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
}
int main(void)
{
    struct list movies = {NULL, NULL, 0};
    if (!append(&movies, "Moss", 8) || !append(&movies, "River", 9)) {
        clear(&movies);
        return EXIT_FAILURE;
    }
    for (const struct node *node = movies.head; node != NULL; node = node->next)
        printf("%s:%d\n", node->title, node->rating);
    clear(&movies);
    printf("empty=%d count=%d\n", movies.head == NULL, movies.count);
    return 0;
}
```

**教学预期（非本平台实测）**：两次分配成功时，先输出Moss:8与River:9，清空后输出empty=1 count=0；若追加失败，已建节点也被清理。节点声明中的指针允许连接同类型节点，并不保证这些节点连续分配。

新节点的片名、评级和终止指针先准备完整，再根据空表或非空表情况更新入口。尾指针让追加不必从头扫描。这里同时设了最多3项的教学边界；动态分配并不意味着容量无限，也仍可能提前失败。

`clear`循环判断当前有效节点，先保存`next`再释放，最后恢复头、尾和数量。不能直接沿书中某处混用`current`和`head`的循环照抄：若判断的变量未同步更新，最后可能再次进入循环并解引用空指针。

# 17.2.2 反思

把所有`malloc`、连接更新和清理散落在业务循环中，虽然能完成一次任务，却让后续修改更容易遗漏边界。反思时应问：操作是否有清楚入口，失败会留下什么状态，资源所有权归谁，遍历能否安全重复。

### 使用列表接口，完整实现保留在独立源文件（完整标准C阅读程序）

用户头、多文件链接、动态分配、嵌套结构和回调超出C6范围。三个文件构成完整标准C程序。

**main.c**

```c
#include <stdio.h>
#include <stdlib.h>
#include "list.h"
void print_item(const Item *item)
{
    printf("%s:%d\n", item->title, item->rating);
}
int main(void)
{
    List movies;
    ListInit(&movies);
    Item first = {"Moss", 8};
    Item second = {"River", 9};
    Item third = {"Dune", 7};
    if (!ListPush(&first, &movies) || !ListPush(&second, &movies) ||
        !ListPush(&third, &movies)) {
        ListClear(&movies);
        return EXIT_FAILURE;
    }
    int extra = ListPush(&first, &movies);
    printf("extra=%d count=%zu\n", extra, ListCount(&movies));
    ListVisit(&movies, print_item);
    ListClear(&movies);
    ListClear(&movies);
    printf("empty=%d count=%zu\n", ListIsEmpty(&movies), ListCount(&movies));
    return 0;
}
```

**list.h**

```c
#ifndef COURSE_FILM_LIST_H
#define COURSE_FILM_LIST_H
#include <stddef.h>
#include <stdbool.h>
#define LIST_CAPACITY 3
typedef struct {
    char title[16];
    int rating;
} Item;
typedef struct list_node ListNode;
typedef struct {
    ListNode *head;
    ListNode *tail;
    size_t count;
} List;
void ListInit(List *list);
bool ListIsEmpty(const List *list);
bool ListIsFull(const List *list);
size_t ListCount(const List *list);
/* 成功追加一个值副本；失败保持原列表。item须为合法的完整记录。 */
bool ListPush(const Item *item, List *list);
/* visit不得删除或修改正在遍历的列表。 */
void ListVisit(const List *list, void (*visit)(const Item *));
void ListClear(List *list);
#endif
```

**list.c**

```c
#include <stdlib.h>
#include "list.h"
struct list_node {
    Item item;
    ListNode *next;
};
void ListInit(List *list)
{
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
}
bool ListIsEmpty(const List *list)
{
    return list->count == 0;
}
bool ListIsFull(const List *list)
{
    return list->count == LIST_CAPACITY;
}
size_t ListCount(const List *list)
{
    return list->count;
}
bool ListPush(const Item *item, List *list)
{
    if (ListIsFull(list))
        return false;
    ListNode *node = malloc(sizeof *node);
    if (node == NULL)
        return false;
    node->item = *item;
    node->next = NULL;
    /* 新节点完整就绪后才接入；失败路径不会破坏原列表。 */
    if (list->tail == NULL)
        list->head = node;
    else
        list->tail->next = node;
    list->tail = node;
    ++list->count;
    return true;
}
void ListVisit(const List *list, void (*visit)(const Item *))
{
    const ListNode *node = list->head;
    while (node != NULL) {
        visit(&node->item);
        node = node->next;
    }
}
void ListClear(List *list)
{
    ListNode *node = list->head;
    while (node != NULL) {
        ListNode *next = node->next;
        free(node);
        node = next;
    }
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
}
```

**教学预期（非本平台实测）**：前三项分配成功时，第四次追加因容量3返回0，count=3；回调依次显示Moss:8、River:9、Dune:7。清空两次后empty=1 count=0。任何分配失败都先清理已建列表，再报告失败终止。

主程序只谈初始化、追加、遍历和清空，节点分配与尾连接集中在实现文件中。追加返回失败时，原列表保持有效；调用者负责决定结束还是重试，而不是默认所有分配总能成功。

这份实现把“满”定义为达到容量3，真正分配仍可能更早失败。先临时`malloc`再立即释放只能探测那一刻的申请结果，不能保证下一次实际追加一定成功，因而不能替代操作内部检查。

# 17.3 抽象数据类型（ADT）

抽象数据类型先描述可观察的属性与操作，再定义程序接口，最后选择具体表示。一个有序列次序的列表可以由链表实现，也可以由数组实现；抽象层没有要求每一项必须带一个指针。

### 使用列表接口，完整实现保留在独立源文件（完整标准C阅读程序）

用户头、多文件链接、动态分配、嵌套结构和回调超出C6范围。三个文件构成完整标准C程序。

**main.c**

```c
#include <stdio.h>
#include <stdlib.h>
#include "list.h"
