#define COURSE_INT_QUEUE_H
#include <stdbool.h>
#define QUEUE_CAPACITY 3
typedef int Item;
typedef struct queue_node QueueNode;
typedef struct {
    QueueNode *front;
    QueueNode *rear;
    int count;
} Queue;
