bool QueueIsEmpty(const Queue *queue);
bool QueueIsFull(const Queue *queue);
int QueueCount(const Queue *queue);
/* 满或分配失败返回false，原队列不变。 */
bool QueuePush(Item item, Queue *queue);
/* 空时返回false，*item不变；输出对象须有效且不与队列内部存储重叠。 */
