**queue.c**

```c
#include <stdlib.h>
#include "queue.h"
struct queue_node {
    Item item;
    QueueNode *next;
};
void QueueInit(Queue *queue)
{
    queue->front = NULL;
    queue->rear = NULL;
    queue->count = 0;
}
bool QueueIsEmpty(const Queue *queue)
{
    return queue->count == 0;
}
bool QueueIsFull(const Queue *queue)
{
    return queue->count == QUEUE_CAPACITY;
}
int QueueCount(const Queue *queue)
{
    return queue->count;
}
bool QueuePush(Item item, Queue *queue)
{
    if (QueueIsFull(queue))
        return false;
    QueueNode *node = malloc(sizeof *node);
    if (node == NULL)
        return false;
    node->item = item;
    node->next = NULL;
    if (queue->rear == NULL)
        queue->front = node;
    else
        queue->rear->next = node;
    queue->rear = node;
    ++queue->count;
    return true;
}
bool QueuePop(Item *item, Queue *queue)
{
    if (QueueIsEmpty(queue))
        return false;
    QueueNode *old = queue->front;
    *item = old->item;
    queue->front = old->next;
    --queue->count;
    /* 删除最后一项后，rear也必须回到空状态。 */
    if (queue->count == 0)
        queue->rear = NULL;
    free(old);
    return true;
}
void QueueClear(Queue *queue)
{
    Item unused;
    while (QueuePop(&unused, queue)) {
    }
}
```

**教学预期（非本平台实测）**：三个节点分配成功时，满队列追加返回0、数量仍3；依次取40、20、55，空时输出变量777不变。空队列再次加入7可正常取出，清空两次后count=0。

入队在容量已满或分配失败时返回假，已有队列保持有效；本例采用可恢复失败，没有从库实现内部直接结束整个程序。`QueueIsFull`只反映规定容量，不能预先证明下一次分配一定可用。

接口要求队列先初始化，输出对象有效且不与内部存储重叠。只读查询的`const`约束访问路径，调用者仍应通过接口修改队列，不能绕过接口随意重写计数或连接。

