# 17.5 用队列进行模拟

模拟前先明确时间和统计口径。这里每轮代表一分钟，先处理本分钟到达，再在服务空闲时从队首取一人，执行一分钟服务，最后采样仍在排队的人数。该顺序会影响容量边界和等待统计，必须明确。

### 固定到达事件区分已接纳、已开始与已完成（完整C程序）

```c
#include <stdio.h>
int main(void)
{
    int minutes;
    if (scanf("%d", &minutes) != 1 || minutes < 1 || minutes > 6) {
        puts("minutes 1..6");
        return 0;
    }
    int arrived[4] = {0, 1, 2, 3};
    int duration[4] = {3, 2, 1, 1};
    int line[2];
    int front = 0;
    int count = 0;
    int next = 0;
    int remaining = 0;
    int accepted = 0;
    int rejected = 0;
    int started = 0;
    int completed = 0;
    int waiting_sum = 0;
    int queue_sum = 0;
    for (int minute = 0; minute < minutes; ++minute) {
        /* 本模型先处理本分钟到达，再处理服务与队列长度采样。 */
        if (next < 4 && arrived[next] == minute) {
            if (count == 2)
                ++rejected;
            else {
                line[(front + count) % 2] = next;
                ++count;
                ++accepted;
            }
            ++next;
        }
        if (remaining == 0 && count > 0) {
            int customer = line[front];
            front = (front + 1) % 2;
            --count;
            waiting_sum += minute - arrived[customer];
            remaining = duration[customer];
            ++started;
        }
        if (remaining > 0) {
            --remaining;
            if (remaining == 0)
                ++completed;
        }
        queue_sum += count;
    }
    printf("accepted=%d rejected=%d started=%d", accepted, rejected, started);
    printf(" completed=%d waiting=%d busy=%d\n", completed, count, remaining > 0);
    double average_wait = started == 0 ? 0.0 : (double)waiting_sum / started;
    printf("average-queue=%.2f average-start-wait=%.2f\n",
           (double)queue_sum / minutes, average_wait);
    return 0;
}
```

**输入**：

```text
6
```

**真实C6运行结果**：

```text
accepted=3 rejected=1 started=3 completed=3 waiting=0 busy=0
average-queue=0.83 average-start-wait=1.67
```

固定事件让结果可核对：到达时刻0、1、2、3，服务时长3、2、1、1，等待队列容量2。模拟到第4分钟结束时，接纳3人、拒绝1人，已开始2人但只完成1人，另有1人等待、1人仍在服务。因此书中在“出队开始服务”时增加的`served`，准确含义应是已开始服务，而不是全都完成。

平均队列长度取每分钟服务后的等待人数平均；平均开始等待时间只对已开始服务者计算，不能拿全部接纳人数作分母。结束时未开始或未完成的顾客仍存在，不会自动补完；分钟数和相关分母都须检查。

### 随机模拟复用队列接口，但统计口径另行定义（完整标准C阅读程序）

rand、srand、动态队列及多文件链接不在C6范围。queue.h改为顾客Item，queue.c实现保持相同；三个文件是完整程序。

**main.c**

```c
#include <stdio.h>
#include <stdlib.h>
#include "queue.h"
int main(void)
{
    const int minutes = 120;
    const double per_hour = 20.0;
    Queue queue;
    QueueInit(&queue);
    srand(7u);
    int accepted = 0, rejected = 0, started = 0, completed = 0;
    int remaining = 0, queue_sum = 0, wait_sum = 0;
    for (int minute = 0; minute < minutes; ++minute) {
        double draw = (double)rand() / ((double)RAND_MAX + 1.0);
        if (draw < per_hour / 60.0) {
            if (QueueIsFull(&queue))
                ++rejected;
            else {
                Item customer = {minute, rand() % 3 + 1};
                if (!QueuePush(customer, &queue)) {
                    QueueClear(&queue);
                    return EXIT_FAILURE;
                }
                ++accepted;
            }
        }
        if (remaining == 0 && !QueueIsEmpty(&queue)) {
            Item customer;
            if (QueuePop(&customer, &queue)) {
                remaining = customer.duration;
                wait_sum += minute - customer.arrived;
                ++started;
            }
        }
        if (remaining > 0 && --remaining == 0)
            ++completed;
        queue_sum += QueueCount(&queue);
    }
    printf("accepted=%d rejected=%d started=%d completed=%d waiting=%d busy=%d\n",
           accepted, rejected, started, completed, QueueCount(&queue), remaining > 0);
    printf("average-queue=%.2f\n", (double)queue_sum / minutes);
    if (started > 0)
        printf("average-start-wait=%.2f\n", (double)wait_sum / started);
    else
        puts("no service started");
    QueueClear(&queue);
    return 0;
}
```

