}
```

**教学预期（非本平台实测）**：固定种子只使同一实现的同次随机序列可复现，不给跨实现固定统计数。成功运行时accepted=started+waiting，started=completed+busy；平均等待分母是已开始服务人数。到达模型每分钟至多一人，结束时不自动继续服务剩余顾客。

随机版复用相同队列实现，只换顾客项类型，最多每分钟到一人，属于离散的简化模型，不能照搬成任意到达率的连续时间现实过程。固定种子不保证跨实现相同统计；`rand()%3`也不是严格无偏随机生成方法。更长样本能减少部分随机波动，但不会自动修复模型假设。

# 17.6 链表和数组

数组提供常数时间的下标定位；普通单向链表需要沿连接走到目标位置。数组在中间插删通常要移动后续元素，链表在已知前驱的位置附近只需改少量连接，但寻找该位置和申请节点的成本不能省略。

### 数组移动元素，链表修改已有位置附近的连接（完整C程序）

```c
#include <stdio.h>
#include <stddef.h>
struct node {
    int value;
    struct node *next;
};
struct node last = {5, NULL};
struct node middle = {3, &last};
struct node first = {1, &middle};
struct node added = {2, NULL};
void show(const struct node *node)
{
    while (node != NULL) {
        printf(" %d", node->value);
        node = node->next;
    }
    putchar('\n');
}
int main(void)
{
    int values[6] = {1, 3, 5};
    int count = 3;
    int position = 1;
    for (int i = count; i > position; --i)
        values[i] = values[i - 1];
    values[position] = 2;
    ++count;
    printf("array-insert:");
    for (int i = 0; i < count; ++i)
        printf(" %d", values[i]);
    putchar('\n');
    position = 2;
    for (int i = position; i + 1 < count; ++i)
        values[i] = values[i + 1];
    --count;
    printf("array-delete:");
    for (int i = 0; i < count; ++i)
        printf(" %d", values[i]);
    putchar('\n');
    added.next = first.next;
    first.next = &added;
    printf("list-insert:");
    show(&first);
    added.next = middle.next;
    printf("list-delete:");
    show(&first);
    return 0;
}
```

**输入**：无需输入。

**真实C6运行结果**：

```text
array-insert: 1 2 3 5
array-delete: 1 2 5
list-insert: 1 2 3 5
list-delete: 1 2 5
```

数组插入从后向前移动，避免覆盖尚未搬走的值；链表先保存旧后继到新节点，再接入前驱。这里的节点是静态对象，删除只把它从链上摘下，没有释放它，也不能对它调用`free`。

### 有序数组二分查找维护剩余闭区间（完整C程序）

```c
#include <stdio.h>
int find(const int values[], int count, int target)
{
    int low = 0;
    int high = count - 1;
    while (low <= high) {
        int middle = low + (high - low) / 2;
        if (values[middle] == target)
            return middle;
        if (values[middle] < target)
            low = middle + 1;
        else
            high = middle - 1;
    }
    return -1;
}
int main(void)
{
    int values[5] = {1, 3, 5, 7, 9};
    printf("five=%d eight=%d first=%d last=%d empty=%d\n",
           find(values, 5, 5), find(values, 5, 8), find(values, 5, 1),
           find(values, 5, 9), find(values, 0, 1));
    return 0;
}
```

**输入**：无需输入。

**真实C6运行结果**：

```text
five=2 eight=-1 first=0 last=4 empty=-1
```

二分查找依赖有序和快速取中间项。普通单链表也能按中点思路分区，但寻找中点仍要走连接，得不到数组那样的整体对数访问效率，不能简单说在链表上“绝对不能”二分。数组也能运行时分配，不是所有数组容量都必须在编译时决定；树同样不是对所有操作都必胜的替代品。

# 17.7 二叉查找树

二叉查找树的每个节点有至多两个子节点。不变量约束整棵子树：左侧所有键都在当前键之前，右侧所有键都在之后，不能只比较两个直接子节点就认为整棵树有效。

### 按整棵子树的次序约定查找与中序遍历（完整C程序）

```c
#include <stdio.h>
#include <stddef.h>
struct node {
    int key;
    struct node *left;
    struct node *right;
};
struct node one = {1, NULL, NULL};
struct node three = {3, NULL, NULL};
struct node five = {5, NULL, NULL};
struct node seven = {7, NULL, NULL};
struct node two = {2, &one, &three};
struct node six = {6, &five, &seven};
struct node four = {4, &two, &six};
int contains(const struct node *root, int key)
{
    const struct node *current = root;
    while (current != NULL) {
        if (key == current->key)
            return 1;
        current = key < current->key ? current->left : current->right;
    }
    return 0;
}
void inorder(const struct node *root)
{
    if (root == NULL)
        return;
    inorder(root->left);
    printf(" %d", root->key);
    inorder(root->right);
}
int height(const struct node *root)
{
    if (root == NULL)
        return 0;
    int left = height(root->left);
    int right = height(root->right);
    return 1 + (left > right ? left : right);
}
int main(void)
{
    int key;
    if (scanf("%d", &key) != 1) {
        puts("no key");
        return 0;
    }
    printf("ordered:");
    inorder(&four);
    putchar('\n');
    printf("key=%d found=%d empty=%d height=%d\n", key,
           contains(&four, key), contains(NULL, key), height(&four));
    return 0;
}
```

**输入**：

```text
3
```

**真实C6运行结果**：

```text
ordered: 1 2 3 4 5 6 7
key=3 found=1 empty=0 height=3
```

查找每次依据次序进入一个子树，遇空入口则表示不存在。中序遍历先左、再当前、再右，在不变量成立时得到升序。这个完整小树用现成节点真实观察查找、遍历和高度，动态增加和删除另有完整阅读实现。

一次比较可以排除另一个子树，却不保证恰好排除一半节点。成本由树高控制，平衡时可为对数级，极端偏斜时会退化为线性。

