#ifndef COURSE_PET_TREE_H
#define COURSE_PET_TREE_H
#include <stdbool.h>
#include <stddef.h>
#define TREE_CAPACITY 7
typedef struct {
    char name[20];
    char kind[20];
} Item;
typedef struct tree_node TreeNode;
typedef struct {
    TreeNode *root;
    size_t count;
} Tree;
enum AddResult { TREE_ADDED, TREE_DUPLICATE, TREE_FULL, TREE_NO_MEMORY };
void TreeInit(Tree *tree);
size_t TreeCount(const Tree *tree);
enum AddResult TreeAdd(const Item *item, Tree *tree);
bool TreeContains(const Item *item, const Tree *tree);
bool TreeRemove(const Item *item, Tree *tree);
