#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <ctype.h>

typedef struct movie { char title[45]; int rating; } Movie;

static int read_line(char *text, int capacity) {
    if (capacity < 2) return -1;
    if (fgets(text, capacity, stdin) == NULL) return ferror(stdin) ? -1 : 0;
    char *end = strchr(text, '\n');
    if (end != NULL) { *end = '\0'; return 1; }
    int ch = getchar();
    if (ch == '\n') return 1;
    if (ch == EOF) return ferror(stdin) ? -1 : 1;
    while (ch != '\n' && ch != EOF) ch = getchar();
    return -1;
}

static int read_movie(Movie *item) {
    int status = read_line(item->title, 45);
    if (status != 1) return status;
    if (item->title[0] == '\0') return 0;
    char number[32];
    if (read_line(number, 32) != 1) return -1;
    char *end;
    errno = 0;
    long rating = strtol(number, &end, 10);
    if (end == number || errno == ERANGE) return -1;
    while (isspace((unsigned char)*end)) end++;
    if (*end != '\0' || rating < 0 || rating > 10) return -1;
    item->rating = (int)rating;
    return 1;
}

int main(void) {
    Movie movies[5];
    int count = 0, failed = 0;
    while (count < 5) {
        int status = read_movie(&movies[count]);
        if (status != 1) { failed = status < 0; break; }
        count++;
    }
    printf("movies=%d\n", count);
    for (int i = 0; i < count; i++) printf("%s:%d\n", movies[i].title, movies[i].rating);
    return failed;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <ctype.h>

typedef struct movie { char title[45]; int rating; struct movie *next; } Movie;

static int read_line(char *text, int capacity) {
    if (capacity < 2) return -1;
    if (fgets(text, capacity, stdin) == NULL) return ferror(stdin) ? -1 : 0;
    char *end = strchr(text, '\n');
    if (end != NULL) { *end = '\0'; return 1; }
    int ch = getchar();
    if (ch == '\n') return 1;
    if (ch == EOF) return ferror(stdin) ? -1 : 1;
    while (ch != '\n' && ch != EOF) ch = getchar();
    return -1;
}

static int read_movie(Movie *item) {
    int status = read_line(item->title, 45);
    if (status != 1) return status;
    if (item->title[0] == '\0') return 0;
    char number[32];
    if (read_line(number, 32) != 1) return -1;
    char *end;
    errno = 0;
    long rating = strtol(number, &end, 10);
    if (end == number || errno == ERANGE) return -1;
    while (isspace((unsigned char)*end)) end++;
    if (*end != '\0' || rating < 0 || rating > 10) return -1;
    item->rating = (int)rating;
    return 1;
}

int main(void) {
    Movie *head = NULL, *tail = NULL;
    Movie temporary = {"", 0, NULL};
    int failed = 0, status;
    while ((status = read_movie(&temporary)) == 1) {
        Movie *node = malloc(sizeof *node);
        if (node == NULL) { failed = 1; break; }
        *node = temporary;
        node->next = NULL;
        if (head == NULL) head = node;
        else tail->next = node;
        tail = node;
    }
    if (status < 0) failed = 1;
    for (const Movie *cursor = head; cursor != NULL; cursor = cursor->next)
        printf("%s:%d\n", cursor->title, cursor->rating);
    while (head != NULL) {
        Movie *old = head;
        head = head->next;
        free(old);
    }
    tail = NULL;
    return failed;
}

