#ifndef CATALOG_API_H
#define CATALOG_API_H
#include <stdbool.h>
typedef struct item { char title[45]; int rating; } Item;
typedef struct node { Item item; struct node *next; } Node;
typedef Node *List;
/* Valid list addresses; Traverse callbacks must not mutate the traversed list. */
void ListInit(List *list);
bool ListEmpty(const List *list);
bool ListFull(const List *list);
unsigned int ListCount(const List *list);
bool ListAdd(Item item, List *list);
void ListEach(const List *list, void (*action)(Item));
void ListClear(List *list);
#endif

#include <stdlib.h>
#include <limits.h>
#include "catalog_api.h"
void ListInit(List *list) { *list = NULL; }
bool ListEmpty(const List *list) { return *list == NULL; }
unsigned int ListCount(const List *list) {
    unsigned int count = 0;
    for (const Node *node = *list; node != NULL; node = node->next) count++;
    return count;
}
bool ListFull(const List *list) {
    if (ListCount(list) == UINT_MAX) return true;
    Node *probe = malloc(sizeof *probe);
    bool unavailable = probe == NULL;
    free(probe);
    return unavailable;
}
bool ListAdd(Item item, List *list) {
    if (ListCount(list) == UINT_MAX) return false;
    Node *node = malloc(sizeof *node);
    if (node == NULL) return false;
    node->item = item;
    node->next = NULL;
    if (*list == NULL) *list = node;
    else {
        Node *last = *list;
        while (last->next != NULL) last = last->next;
        last->next = node;
    }
    return true;
}
void ListEach(const List *list, void (*action)(Item)) {
    for (const Node *node = *list; node != NULL; node = node->next) action(node->item);
}
void ListClear(List *list) {
    while (*list != NULL) {
        Node *old = *list;
        *list = old->next;
        free(old);
    }
}

