#ifndef TICKET_API_H
#define TICKET_API_H
#include <stdbool.h>
#define QUEUE_CAPACITY 10
typedef int Item;
typedef struct qnode { Item item; struct qnode *next; } QNode;
typedef struct queue { QNode *front; QNode *rear; int count; } Queue;
/* Initialized queues; Pop output is a separate writable Item object. */
void QInit(Queue *queue);
bool QEmpty(const Queue *queue);
bool QFull(const Queue *queue);
int QCount(const Queue *queue);
bool QPush(Item item, Queue *queue);
bool QPop(Item *item, Queue *queue);
void QClear(Queue *queue);
#endif

#include <stdlib.h>
#include "ticket_api.h"
void QInit(Queue *queue) { queue->front = queue->rear = NULL; queue->count = 0; }
bool QEmpty(const Queue *queue) { return queue->count == 0; }
bool QFull(const Queue *queue) { return queue->count >= QUEUE_CAPACITY; }
int QCount(const Queue *queue) { return queue->count; }
bool QPush(Item item, Queue *queue) {
    if (QFull(queue)) return false;
    QNode *node = malloc(sizeof *node);
    if (node == NULL) return false;
    node->item = item;
    node->next = NULL;
    if (QEmpty(queue)) queue->front = node;
    else queue->rear->next = node;
    queue->rear = node;
    queue->count++;
    return true;
}
bool QPop(Item *item, Queue *queue) {
    if (QEmpty(queue)) return false;
    QNode *old = queue->front;
    *item = old->item;
    queue->front = old->next;
    queue->count--;
    if (queue->count == 0) queue->rear = NULL;
    free(old);
    return true;
}
void QClear(Queue *queue) {
    Item discarded;
    while (!QEmpty(queue)) QPop(&discarded, queue);
}

