#ifndef ROSTER_API_H
#define ROSTER_API_H
#include <stdbool.h>
#define TREE_CAPACITY 10
typedef struct item { char name[20]; char kind[20]; } Item;
typedef struct tnode { Item item; struct tnode *left; struct tnode *right; } TNode;
typedef struct tree { TNode *root; int size; } Tree;
/* Valid initialized trees and NUL-terminated keys; Each callbacks do not mutate the tree. */
void TreeInit(Tree *tree);
bool TreeEmpty(const Tree *tree);
bool TreeFull(const Tree *tree);
int TreeCount(const Tree *tree);
bool TreeAdd(const Item *item, Tree *tree);
bool TreeContains(const Item *item, const Tree *tree);
bool TreeRemove(const Item *item, Tree *tree);
void TreeEach(const Tree *tree, void (*action)(Item));
void TreeClear(Tree *tree);
#endif

#include <stdlib.h>
#include <string.h>
#include "roster_api.h"
static int compare(const Item *left, const Item *right) {
    int names = strcmp(left->name, right->name);
    return names != 0 ? names : strcmp(left->kind, right->kind);
}
void TreeInit(Tree *tree) { tree->root = NULL; tree->size = 0; }
bool TreeEmpty(const Tree *tree) { return tree->size == 0; }
bool TreeFull(const Tree *tree) { return tree->size >= TREE_CAPACITY; }
int TreeCount(const Tree *tree) { return tree->size; }
bool TreeContains(const Item *item, const Tree *tree) {
    const TNode *node = tree->root;
    while (node != NULL) {
        int direction = compare(item, &node->item);
        if (direction == 0) return true;
        node = direction < 0 ? node->left : node->right;
    }
    return false;
}
bool TreeAdd(const Item *item, Tree *tree) {
    if (TreeFull(tree)) return false;
    TNode **link = &tree->root;
    while (*link != NULL) {
        int direction = compare(item, &(*link)->item);
        if (direction == 0) return false;
        link = direction < 0 ? &(*link)->left : &(*link)->right;
    }
    TNode *node = malloc(sizeof *node);
    if (node == NULL) return false;
    node->item = *item;
    node->left = node->right = NULL;
    *link = node;
    tree->size++;
    return true;
}
bool TreeRemove(const Item *item, Tree *tree) {
    TNode **link = &tree->root;
    while (*link != NULL) {
        int direction = compare(item, &(*link)->item);
        if (direction == 0) break;
        link = direction < 0 ? &(*link)->left : &(*link)->right;
    }
    if (*link == NULL) return false;
    TNode *old = *link;
    if (old->left == NULL) *link = old->right;
    else if (old->right == NULL) *link = old->left;
    else {
        TNode *last = old->left;
        while (last->right != NULL) last = last->right;
        last->right = old->right;
        *link = old->left;
    }
    free(old);
    tree->size--;
    return true;
}
static void in_order(const TNode *node, void (*action)(Item)) {
    if (node == NULL) return;
    in_order(node->left, action);
    action(node->item);
    in_order(node->right, action);
}
void TreeEach(const Tree *tree, void (*action)(Item)) {
    if (action != NULL) in_order(tree->root, action);
}
static void clear_nodes(TNode *node) {
    if (node == NULL) return;
    clear_nodes(node->left);
    clear_nodes(node->right);
    free(node);
}
void TreeClear(Tree *tree) {
    if (tree == NULL) return;
    clear_nodes(tree->root);
    tree->root = NULL;
    tree->size = 0;
}

