#include <stdio.h>
#include <string.h>
#include <ctype.h>
#include "club_api.h"

static int read_line(char *text, int capacity) {
    if (capacity < 2) return -1;
    if (fgets(text, capacity, stdin) == NULL) return ferror(stdin) ? -1 : 0;
    char *end = strchr(text, '\n');
    if (end != NULL) { *end = '\0'; return 1; }
    int ch = getchar();
    if (ch == '\n') return 1;
    if (ch == EOF) return ferror(stdin) ? -1 : 1;
    while (ch != '\n' && ch != EOF) ch = getchar();
    return -1;
}

static int normalize(char *text) {
    for (; *text != '\0'; text++) {
        unsigned char ch = (unsigned char)*text;
        if (ch < 32 || ch > 126) return 0;
        *text = (char)toupper(ch);
    }
    return 1;
}
static int read_pet(Item *item) {
    int status = read_line(item->name, 20);
    if (status != 1) return status;
    status = read_line(item->kind, 20);
    if (status != 1) return status;
    if (item->name[0] == '\0' || item->kind[0] == '\0' ||
        !normalize(item->name) || !normalize(item->kind)) return -1;
    return 1;
}
static int menu(void) {
    int choice = getchar();
    if (choice == EOF) return EOF;
    if (choice != '\n') {
        int tail;
        while ((tail = getchar()) != '\n' && tail != EOF) {}
    }
    choice = tolower((unsigned char)choice);
    if (choice == 'a' || choice == 'l' || choice == 'n' ||
        choice == 'f' || choice == 'd' || choice == 'q') return choice;
    return '?';
}
void show_pet(Item item) { printf("%s/%s\n", item.name, item.kind); }

int main(void) {
    Tree pets;
    TreeInit(&pets);
    int failed = 0;
    while (1) {
        puts("a add | l list | n count | f find | d delete | q quit");
        int choice = menu();
        if (choice == EOF || choice == 'q') break;
        if (choice == 'l') {
            if (TreeEmpty(&pets)) puts("EMPTY");
            else TreeEach(&pets, show_pet);
        } else if (choice == 'n') printf("count=%d\n", TreeCount(&pets));
        else if (choice == 'a' || choice == 'f' || choice == 'd') {
            Item item = {"", ""};
            int status = read_pet(&item);
            if (status == 0) break;
            if (status < 0) {
                if (ferror(stdin)) { failed = 1; break; }
                puts("INVALID PET");
                continue;
            }
            if (choice == 'a') {
                if (TreeContains(&item, &pets)) puts("DUPLICATE");
                else if (TreeFull(&pets)) puts("FULL");
                else puts(TreeAdd(&item, &pets) ? "ADDED" : "ADD FAILED");
            } else if (choice == 'f') puts(TreeContains(&item, &pets) ? "FOUND" : "ABSENT");
            else puts(TreeRemove(&item, &pets) ? "REMOVED" : "ABSENT");
        } else puts("INVALID MENU");
    }
    if (ferror(stdin)) failed = 1;
    TreeClear(&pets);
    return failed;
}

