}
static void in_order(const TNode *node, void (*action)(Item)) {
    if (node == NULL) return;
    in_order(node->left, action);
    action(node->item);
    in_order(node->right, action);
}
void TreeEach(const Tree *tree, void (*action)(Item)) {
    if (action != NULL) in_order(tree->root, action);
}
static void clear_nodes(TNode *node) {
    if (node == NULL) return;
    clear_nodes(node->left);
    clear_nodes(node->right);
    free(node);
}
void TreeClear(Tree *tree) {
    if (tree == NULL) return;
    clear_nodes(tree->root);
    tree->root = NULL;
    tree->size = 0;
}

