#endif

#include <stdlib.h>
#include "list.h"
struct list_node {
    Item item;
    ListNode *next;
};
void ListInit(List *list)
{
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
}
bool ListIsEmpty(const List *list)
{
    return list->count == 0;
}
bool ListIsFull(const List *list)
{
    return list->count == LIST_CAPACITY;
}
size_t ListCount(const List *list)
{
    return list->count;
}
bool ListPush(const Item *item, List *list)
{
    if (ListIsFull(list))
        return false;
    ListNode *node = malloc(sizeof *node);
    if (node == NULL)
        return false;
    node->item = *item;
    node->next = NULL;
    /* 新节点完整就绪后才接入；失败路径不会破坏原列表。 */
    if (list->tail == NULL)
        list->head = node;
    else
        list->tail->next = node;
    list->tail = node;
    ++list->count;
    return true;
}
void ListVisit(const List *list, void (*visit)(const Item *))
{
    const ListNode *node = list->head;
    while (node != NULL) {
        visit(&node->item);
        node = node->next;
    }
}
void ListClear(List *list)
{
    ListNode *node = list->head;
    while (node != NULL) {
        ListNode *next = node->next;
        free(node);
        node = next;
    }
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
}

