    TreeVisit(&pets, print_item);
    removed = TreeRemove(&extra, &pets);
    printf("missing=%d count=%zu\n", removed, TreeCount(&pets));
    TreeClear(&pets);
    TreeClear(&pets);
    printf("count=%zu\n", TreeCount(&pets));
    return 0;
}

#ifndef COURSE_PET_TREE_H
#define COURSE_PET_TREE_H
#include <stdbool.h>
#include <stddef.h>
#define TREE_CAPACITY 7
typedef struct {
    char name[20];
    char kind[20];
} Item;
typedef struct tree_node TreeNode;
typedef struct {
    TreeNode *root;
    size_t count;
} Tree;
enum AddResult { TREE_ADDED, TREE_DUPLICATE, TREE_FULL, TREE_NO_MEMORY };
void TreeInit(Tree *tree);
size_t TreeCount(const Tree *tree);
enum AddResult TreeAdd(const Item *item, Tree *tree);
bool TreeContains(const Item *item, const Tree *tree);
bool TreeRemove(const Item *item, Tree *tree);
/* visit不得修改本树的结构或参与排序的键。 */
void TreeVisit(const Tree *tree, void (*visit)(const Item *));
void TreeClear(Tree *tree);
#endif

#include <stdlib.h>
#include <string.h>
#include "tree.h"
struct tree_node {
    Item item;
    TreeNode *left;
    TreeNode *right;
};
static int compare(const Item *a, const Item *b)
{
    int order = strcmp(a->name, b->name);
    return order != 0 ? order : strcmp(a->kind, b->kind);
}
void TreeInit(Tree *tree)
{
    tree->root = NULL;
    tree->count = 0;
}
size_t TreeCount(const Tree *tree)
{
    return tree->count;
}
enum AddResult TreeAdd(const Item *item, Tree *tree)
{
    TreeNode **link = &tree->root;
    while (*link != NULL) {
        int order = compare(item, &(*link)->item);
        if (order == 0)
            return TREE_DUPLICATE;
        link = order < 0 ? &(*link)->left : &(*link)->right;
    }
    if (tree->count == TREE_CAPACITY)
        return TREE_FULL;
    TreeNode *node = malloc(sizeof *node);
    if (node == NULL)
        return TREE_NO_MEMORY;
    node->item = *item;
    node->left = NULL;
    node->right = NULL;
    *link = node;
    ++tree->count;
    return TREE_ADDED;
}
bool TreeContains(const Item *item, const Tree *tree)
{
    const TreeNode *node = tree->root;
    while (node != NULL) {
        int order = compare(item, &node->item);
        if (order == 0)
            return true;
        node = order < 0 ? node->left : node->right;
    }
    return false;
}
bool TreeRemove(const Item *item, Tree *tree)
{
    TreeNode **link = &tree->root;
    while (*link != NULL) {
        int order = compare(item, &(*link)->item);
        if (order == 0)
            break;
        link = order < 0 ? &(*link)->left : &(*link)->right;
    }
    if (*link == NULL)
        return false;
    TreeNode *old = *link;
    if (old->left == NULL)
        *link = old->right;
    else if (old->right == NULL)
        *link = old->left;
    else {
        /* 右子树的全部键都大于左子树，接到左子树最右端仍保持有序。 */
        TreeNode *largest = old->left;
        while (largest->right != NULL)
            largest = largest->right;
        largest->right = old->right;
        *link = old->left;
    }
    --tree->count;
    free(old);
    return true;
}
static void visit_nodes(const TreeNode *node, void (*visit)(const Item *))
{
    if (node == NULL)
        return;
    visit_nodes(node->left, visit);
    visit(&node->item);
    visit_nodes(node->right, visit);
}
void TreeVisit(const Tree *tree, void (*visit)(const Item *))
{
    visit_nodes(tree->root, visit);
}
static void clear_nodes(TreeNode *node)
{
    if (node == NULL)
        return;
    clear_nodes(node->left);
    clear_nodes(node->right);
    free(node);
}
void TreeClear(Tree *tree)
{
    clear_nodes(tree->root);
    tree->root = NULL;
    tree->count = 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include "tree.h"
int read_line(char text[], int capacity)
{
    if (fgets(text, capacity, stdin) == NULL)
        return 0;
    char *newline = strchr(text, '\n');
    if (newline != NULL) {
        *newline = '\0';
        return 1;
    }
    int ch = getchar();
    if (ch == '\n' || ch == EOF)
        return 1;
    while (ch != '\n' && ch != EOF)
        ch = getchar();
    return -1;
}
int read_item(Item *item)
{
    puts("name:");
    int status = read_line(item->name, 20);
    if (status <= 0)
        return status;
    puts("kind:");
    status = read_line(item->kind, 20);
    if (status <= 0)
        return status;
    if (item->name[0] == '\0' || item->kind[0] == '\0')
        return -1;
    for (size_t i = 0; item->name[i] != '\0'; ++i)
        item->name[i] = (char)toupper((unsigned char)item->name[i]);
    for (size_t i = 0; item->kind[i] != '\0'; ++i)
        item->kind[i] = (char)toupper((unsigned char)item->kind[i]);
    return 1;
}
void print_item(const Item *item)
{
    printf("%s %s\n", item->name, item->kind);
}
int main(void)
{
    Tree pets;
    TreeInit(&pets);
    char command[8];
    for (;;) {
        puts("a:add f:find d:delete l:list n:count q:quit");
        int status = read_line(command, 8);
        if (status == 0)
            break;
        if (status < 0 || command[0] == '\0' || command[1] != '\0') {
            puts("invalid command");
            continue;
        }
        int choice = tolower((unsigned char)command[0]);
        if (choice == 'q')
            break;
        if (choice == 'l') {
            TreeVisit(&pets, print_item);
            continue;
        }
        if (choice == 'n') {
            printf("count=%zu\n", TreeCount(&pets));
            continue;
        }
        if (choice != 'a' && choice != 'f' && choice != 'd') {
            puts("invalid command");
            continue;
        }
        Item item;
        status = read_item(&item);
        if (status == 0)
            break;
        if (status < 0) {
            puts("invalid item");
            continue;
        }
        if (choice == 'f')
            printf("found=%d\n", TreeContains(&item, &pets));
        else if (choice == 'd')
            printf("removed=%d\n", TreeRemove(&item, &pets));
        else {
            enum AddResult result = TreeAdd(&item, &pets);
            if (result == TREE_ADDED)
                puts("added");
            else if (result == TREE_DUPLICATE)
                puts("duplicate");
            else if (result == TREE_FULL)
                puts("full");
            else
                puts("no memory");
        }
    }
    TreeClear(&pets);
    return 0;
}

