    struct node *right;
};
struct node low = {1, NULL, NULL};
struct node high = {3, NULL, NULL};
struct node balanced = {2, &low, &high};
struct node end = {3, NULL, NULL};
struct node second = {2, NULL, &end};
struct node chain = {1, NULL, &second};
int height(const struct node *node)
{
    if (node == NULL)
        return 0;
    int left = height(node->left);
    int right = height(node->right);
    return 1 + (left > right ? left : right);
}
