}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>
struct node {
    char word[16];
    int count;
    struct node *left;
    struct node *right;
};
int add_word(struct node **link, const char *word)
{
    if (strlen(word) >= 16)
        return 0;
    while (*link != NULL) {
        int order = strcmp(word, (*link)->word);
        if (order == 0) {
            if ((*link)->count == INT_MAX)
                return 0;
            ++(*link)->count;
            return 1;
        }
        link = order < 0 ? &(*link)->left : &(*link)->right;
    }
    struct node *node = malloc(sizeof *node);
    if (node == NULL)
        return 0;
    strcpy(node->word, word);
    node->count = 1;
    node->left = NULL;
    node->right = NULL;
    *link = node;
    return 1;
}
void show(const struct node *node)
{
    if (node == NULL)
        return;
    show(node->left);
    printf("%s:%d\n", node->word, node->count);
    show(node->right);
}
void clear(struct node *node)
{
    if (node == NULL)
        return;
    clear(node->left);
    clear(node->right);
    free(node);
}
int main(void)
{
    const char *words[6] = {"moss", "fern", "moss", "oak", "fern", "moss"};
    struct node *root = NULL;
    for (int i = 0; i < 6; ++i) {
        if (!add_word(&root, words[i])) {
            clear(root);
            return EXIT_FAILURE;
        }
    }
    show(root);
    clear(root);
    root = NULL;
    return 0;
}
